(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  window.scrollTo({ top: 640, behavior: 'instant' });
  await sleep(300);
  const out = {};
  const markers = [...document.querySelectorAll('.map-marker')];
  out.markerCount = markers.length;
  const marker = markers.find((m) => m.getBoundingClientRect().top > 120 && m.getBoundingClientRect().bottom < 800) ?? markers[0];
  out.markerText = marker?.textContent;
  const id = marker?.dataset.id;
  // hover the marker
  marker.dispatchEvent(new PointerEvent('pointerenter', { bubbles: false }));
  await sleep(400);
  const preview = document.querySelector('.map-preview');
  out.preview = { hidden: preview.hidden, text: preview.textContent.replace(/\s+/g, ' ').trim().slice(0, 120), thumb: preview.querySelector('img')?.src?.slice(0, 60) || null, style: preview.getAttribute('style'), rect: (({ left, top, width, height }) => ({ left: Math.round(left), top: Math.round(top), width: Math.round(width), height: Math.round(height) }))(preview.getBoundingClientRect()) };
  out.rowHighlightOnMarkerHover = document.querySelector('.zh-result.is-preview')?.dataset.recordId;
  marker.dispatchEvent(new PointerEvent('pointerleave', { bubbles: false }));
  await sleep(200);
  out.previewAfterLeave = document.querySelector('.map-preview').hidden;
  out.rowAfterLeave = document.querySelector('.zh-result.is-preview')?.dataset.recordId ?? null;
  // hover a result row
  const row = document.querySelector(`.zh-result[data-record-id="${CSS.escape(id)}"]`);
  out.hasRow = Boolean(row);
  row?.dispatchEvent(new PointerEvent('pointerover', { bubbles: true }));
  await sleep(200);
  out.markerHighlightOnRowHover = document.querySelector('.map-marker.is-preview')?.dataset.id ?? null;
  row?.dispatchEvent(new PointerEvent('pointerout', { bubbles: true, relatedTarget: null }));
  await sleep(200);
  out.markerHighlightAfterRowOut = document.querySelector('.map-marker.is-preview')?.dataset.id ?? null;
  // select via marker click -> inline transform must include the scale
  marker.click();
  await sleep(500);
  out.selectedTransform = marker.style.transform;
  out.selectedClass = marker.className;
  // fit control
  const fit = [...document.querySelectorAll('.map-controls button')].find((b) => /einpassen/i.test(b.getAttribute('aria-label') || ''));
  out.fitButton = Boolean(fit);
  const before = location.search;
  fit?.click();
  await sleep(600);
  out.fitChangedUrl = before !== location.search;
  out.urlAfterFit = location.search;
  return out;
})()
